import React, { useState, useEffect } from "react";
import CryptoJS from "crypto-js";
import bcrypt from "bcryptjs";
import usersData from "../data/users.json"; // Import users data
import ksValue from "../data/ks.json"; // Import users data
import VideoProvider from "../context/VideoContext";
import ScrollingCards from "../components/ScrollingCards";
import AccountLockedMessage from "./AccountLockedMessage";
import AccountExpiredMessage from "./AccountExpiredMessage";
import "../App.css";
import "../styles/PasswordProtection.css"
import { UserRequest } from "../models/UserRequest.js";
import { accountLockStatus } from "../services/accountService.js";
import startDevToolsDetection from '../services/devToolsDetection';  // Import the detection function
import {
  openDB,
  getKSValueFromDB,
  getUserFromDB,
  saveUsersToDB,
  getStoredAttempts,
  updateStoredAttempts,
  resetStoredAttempts,
} from "../services/apiService"; // Import API service functions

const MAX_ATTEMPTS = 3;
const API_KEY = "aVo39j49q6w5z8hu5hzuyo36qckf1drq1y!s";
const DB_NAME = "UserDatabase";
const DB_VERSION = 1;
const STORE_NAME = "users";
const ATTEMPTS_STORE = "loginAttempts";
const KS_STORE_NAME = "talam";

const PasswordProtection = ({ onPasswordSuccess }) => {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState(false);
  const [loading, setLoading] = useState(false);
  const [isBlocked, setIsBlocked] = useState(false);
  const [accessExpired, setAccessExpired] = useState(false);
  const [showNewUserMessage, setShowNewUserMessage] = useState(true);

  useEffect(() => {
    startDevToolsDetection();  // Start DevTools detection when the app mounts
    document.getElementById("email").focus();

    // Initialize IndexedDB with users data
    openDB().then(async (db) => {
      const transaction = db.transaction(STORE_NAME, "readonly");
      const store = transaction.objectStore(STORE_NAME);
      const request = store.getAll();

      request.onsuccess = async () => {
        if (request.result.length === 0) {
          await saveUsersToDB(usersData);
        }
      };
    });
  }, []);

  const isEmailValid = email.includes("@gmail.com");
  const isPasswordValid = password.length >= 10;

  const handleKeyDown = (event) => {
    if (event.key === "Enter" && isEmailValid && isPasswordValid) {
      handleSubmit();
    }
  };

  // Improved decryption function with better error handling
  const decryptData = async (encryptedData) => {
    try {
      if (!encryptedData) return null; // Check if data exists
      const ks = await getKSValueFromDB();
      const bytes = CryptoJS.AES.decrypt(encryptedData, ks.ksvalue);
      const decryptedString = bytes.toString(CryptoJS.enc.Utf8);

      if (!decryptedString) throw new Error("Decryption failed or returned empty string");

      return decryptedString;
    } catch (error) {
      console.error("Error decrypting data:", error);
      return null;
    }
  };

  // Check if the user access is expired
  const checkUserValidity = async (validity) => {
    try {
      const createdOnStr = await decryptData(validity.createdOn);
      const validForStr = await decryptData(validity.validFor);

      if (!createdOnStr || !validForStr) return false; // Ensure both values are valid

      const createdOn = new Date(createdOnStr);
      const validForDays = parseInt(validForStr, 10);

      if (isNaN(validForDays)) return false; // Ensure it's a valid number

      const expiryDate = new Date(createdOn);
      expiryDate.setDate(expiryDate.getDate() + validForDays);

      return expiryDate >= new Date();
    } catch (error) {
      console.error("Error checking user validity:", error);
      return false;
    }
  };

  const handleSubmit = async () => {
    if (isBlocked) return;
    setLoading(true);
    setShowNewUserMessage(false);

    setTimeout(async () => {
      const user = await getUserFromDB(email.replace("@gmail.com", ""));
      if (user) {
        const requestData = new UserRequest(email, API_KEY, false, "lockStatus");
        const apiResponse = await accountLockStatus(requestData);
        const storedAttempts = await getStoredAttempts(email);
        if (!apiResponse.success || apiResponse.data.status === 404 ||
          apiResponse.data.message === "User account is locked"
        ) {
          setIsBlocked(true);
          setError(false);
          setLoading(false);
          return;
        }
        if (apiResponse.locked) {
          setIsBlocked(true);
          setError(false);
          setLoading(false);
          return;
        }

        if (user.status.accessExpired) {
          setAccessExpired(true);
          setLoading(false);
          return;
        }

        // Check if access is expired
        const isUserValid = await checkUserValidity(user.validity);
        if (!isUserValid) {
          // Here we update the accessExpired field within the user status object, similar to isBlocked
          user.status.accessExpired = true;
          await saveUsersToDB([user]);
          setAccessExpired(true); // Set local accessExpired state
          setLoading(false);
          return;
        }

        const isMatch = await bcrypt.compare(password, user.credentials.password);
        if (isMatch) {
          await resetStoredAttempts(email);
          const requestData = new UserRequest(email, API_KEY, true, "reset");
          const apiResponse = await accountLockStatus(requestData);
          console.log(apiResponse);
          onPasswordSuccess();
        } else {
          const requestData = new UserRequest(email, API_KEY, false, "failedAttempt");
          const apiResponse = await accountLockStatus(requestData);
          console.log(apiResponse);
          const newAttempts = storedAttempts + 1;
          await updateStoredAttempts(email, newAttempts);
          setError(true);

          if (newAttempts >= MAX_ATTEMPTS) {
            user.status.isBlocked = true;
            await saveUsersToDB([user]);
            setIsBlocked(true);
            setError(false);
          }
        }
      } else {
        setError(true);
      }
      setLoading(false);
    }, 2000);
  };

  return (
    <div>
      {loading && (
        <div className="preloader-container">
          <div className="loader"></div>
        </div>
      )}
      <div className="scrolling-cards-container">
        <VideoProvider>
          <ScrollingCards />
        </VideoProvider>
      </div>
      <div className="container" style={{ textAlign: "center", padding: "20px" }}>
        <h1>Welcome to PTE CORE Practice Platform Website</h1>
        <h2>Please enter your email and password to continue</h2>
        {showNewUserMessage && (
          <div style={{ marginBottom: "15px", color: "#333" }}>
            <strong>New Users: </strong>
            <a
              href="https://www.example.com/tutorial-video"
              target="_blank"
              rel="noopener noreferrer"
              style={{ textDecoration: "none", color: "blue", fontWeight: "bold" }}
            >
              Click here
            </a>
            &nbsp;and follow the steps to get access to the website.
          </div>
        )}

        {/* Email input field */}
        <input
          id="email"
          type="email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          onKeyDown={handleKeyDown} // Listen for Enter key
          placeholder="Enter your email address"
           className="auth-input"
          disabled={loading || isBlocked || accessExpired} // Disable input when loading
          onCopy={(e) => e.preventDefault()} // Disable copy
          onPaste={(e) => e.preventDefault()} // Disable paste
        />

        {/* Password input field */}
        <input
          type="password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          onKeyDown={handleKeyDown} // Listen for Enter key
          placeholder="Enter password"
          className="auth-input"
          disabled={loading || isBlocked || accessExpired} // Disable input when loading
          onCopy={(e) => e.preventDefault()} // Disable copy
          onPaste={(e) => e.preventDefault()} // Disable paste
        />
         {/* Submit button */}
        <button onClick={handleSubmit} disabled={!isEmailValid || !isPasswordValid || loading || isBlocked || accessExpired}>Submit</button>
        {/* {error && <p style={{ color: "red" }}>Incorrect email or password.</p>} */}
        {/* Error Message */}
        {error && (
          <div>
            <p style={{ color: 'red' }}>Incorrect email or password. Please try again.</p>
            <p>Too many incorrect attempts will result in your account being locked.</p>
            <p>
              If you've forgotten your password, please
              <a
                href="https://www.youtube.com/channel/UCMJeoG6jGrGtk3noLZ6bJMg?sub_confirmation=1"
                target="_blank"
                rel="noopener noreferrer"
                style={{ textDecoration: 'none', color: 'blue', fontWeight: 'bold', marginLeft: '5px' }}
              >
                contact the admin over here
              </a>.
            </p>
          </div>
        )}
        {isBlocked && <AccountLockedMessage />}
        {accessExpired && <AccountExpiredMessage />}
      </div>
    </div>
  );
};

export default PasswordProtection;
