// apiService.js - Handles IndexedDB interactions for user authentication and key storage
import usersData from "../data/users.json"; // Import users data
import ksValue from "../data/ks.json"; // Import users data

const DB_NAME = "UserDatabase";
const DB_VERSION = 1;
const STORE_NAME = "users";
const ATTEMPTS_STORE = "loginAttempts";
const KS_STORE_NAME = "talam";

export const openDB = () => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = (event) => {
      const db = event.target.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        const store = db.createObjectStore(STORE_NAME, { keyPath: "email" });
        store.transaction.oncomplete = () => {
          const transaction = db.transaction(STORE_NAME, "readwrite");
          const userStore = transaction.objectStore(STORE_NAME);
          usersData.forEach(user => userStore.put(user)); // Insert users initially
        };
      }
      // Create the ks store if it doesn't exist
      if (!db.objectStoreNames.contains(KS_STORE_NAME)) {
        const ksStore = db.createObjectStore(KS_STORE_NAME, { keyPath: "id" });
        ksStore.transaction.oncomplete = () => {
          const transaction = db.transaction(KS_STORE_NAME, "readwrite");
          const ksStoreObj = transaction.objectStore(KS_STORE_NAME);
          ksStoreObj.put({ id: "key", ks: ksValue }); // Insert initial ks value, can replace "d" with your dynamic value
        };
      }
      if (!db.objectStoreNames.contains(ATTEMPTS_STORE)) {
        db.createObjectStore(ATTEMPTS_STORE, { keyPath: "email" });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

// Fetches the encryption key from IndexedDB
export const getKSValueFromDB = async () => {
  const db = await openDB();
  return new Promise((resolve) => {
    const transaction = db.transaction(KS_STORE_NAME, "readonly");
    const store = transaction.objectStore(KS_STORE_NAME);
    const request = store.get("key");
    request.onsuccess = () => resolve(request.result ? request.result.ks : null);
  });
};

// Retrieves a user from IndexedDB
export const getUserFromDB = async (email) => {
  const db = await openDB();
  return new Promise((resolve) => {
    const transaction = db.transaction(STORE_NAME, "readonly");
    const store = transaction.objectStore(STORE_NAME);
    const request = store.get(email);
    request.onsuccess = () => resolve(request.result || null);
  });
};

// Saves or updates users in IndexedDB
export const saveUsersToDB = async (users) => {
  const db = await openDB();
  const transaction = db.transaction(STORE_NAME, "readwrite");
  const store = transaction.objectStore(STORE_NAME);
  users.forEach(user => store.put(user));
};

// Fetches the stored number of login attempts
export const getStoredAttempts = async (email) => {
  const db = await openDB();
  return new Promise((resolve) => {
    const transaction = db.transaction(ATTEMPTS_STORE, "readonly");
    const store = transaction.objectStore(ATTEMPTS_STORE);
    const request = store.get(email);
    request.onsuccess = () => resolve(request.result ? request.result.attempts : 0);
  });
};

// Updates the login attempt count in IndexedDB
export const updateStoredAttempts = async (email, attempts) => {
  const db = await openDB();
  const transaction = db.transaction(ATTEMPTS_STORE, "readwrite");
  const store = transaction.objectStore(ATTEMPTS_STORE);
  store.put({ email, attempts });
};

// Resets login attempts for a user
export const resetStoredAttempts = async (email) => {
  const db = await openDB();
  const transaction = db.transaction(ATTEMPTS_STORE, "readwrite");
  const store = transaction.objectStore(ATTEMPTS_STORE);
  store.delete(email);
};
